package org.genhttp.modules.clientcaching

import org.genhttp.modules.clientcaching.policy.CachePolicyBuilder
import org.genhttp.modules.clientcaching.validation.CacheValidationBuilder

/**
 * Entry point to create concerns that control how clients cache the content generated by the server.
 */
public object ClientCache {

    /**
     * Creates a concern that will tag content generated by the server so the clients can check,
     * whether new content is available on the server.
     */
    public fun validation(): CacheValidationBuilder = CacheValidationBuilder()

    /**
     * Creates a policy defining how the client should cache the content generated by the server.
     */
    public fun policy(): CachePolicyBuilder = CachePolicyBuilder()

}
